mapper.update:
update member
set bind_status = 'bound', updated_at = current_timestamp
where id = #{memberId} and tenant_id = #{tenantId}

update auth_session
set tenant_id = #{tenantId}
where actor_type = 'member' and subject_id = #{subjectId} and revoked_at is null

mapper.select:
insert into booking(tenant_id, store_id, bookable_slot_id, member_id, member_card_id)
select #{tenantId}, bs.store_id, bs.id, #{memberId}, #{memberCardId}
from bookable_slot bs
where bs.id = #{slotId} and bs.tenant_id = #{tenantId}
returning id
